// GS Poster Twin Orbs brand assets v1 (2026-11-18), generated from
// GSGrimoire/gs-tools-hub branding/twin-orbs/v1/assets/gs-poster/ by Claude.
// Browser-tab icons use the product orb; /brand-logo.png is the full logo at 96 px.
// Do not edit by hand: regenerate from the canonical kit.

const ASSETS: Record<string, { type: string; b64: string }> = {
  "/favicon.ico": { type: "image/x-icon", b64: "" },
  "/favicon-32.png": { type: "image/png", b64: "" },
  "/favicon-16.png": { type: "image/png", b64: "" },
  "/apple-touch-icon.png": { type: "image/png", b64: "" },
  "/brand-logo.png": { type: "image/png", b64: "" },
};

function bytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** Paths served by brandAsset(), for tests. */
export const BRAND_PATHS = Object.keys(ASSETS);

/** Head tags for every HTML page. */
export const BRAND_HEAD = '<link rel="icon" href="/favicon.ico" sizes="48x48"><link rel="icon" type="image/png" sizes="32x32" href="/favicon-32.png"><link rel="icon" type="image/png" sizes="16x16" href="/favicon-16.png"><link rel="apple-touch-icon" href="/apple-touch-icon.png">';

/** Public, static brand images. Returns null for any other path or method. */
export function brandAsset(req: Request, path: string): Response | null {
  const a = ASSETS[path];
  if (!a || (req.method !== "GET" && req.method !== "HEAD")) return null;
  return new Response(req.method === "HEAD" ? null : bytes(a.b64), { headers: {
    "Content-Type": a.type, "Cache-Control": "public, max-age=86400",
    "X-Content-Type-Options": "nosniff", "Content-Security-Policy": "default-src 'none'",
  } });
}
